import numpy as np
d=np.load('train.npy')
J,V,Ci,Co=d
from scipy.optimize import least_squares
rng=np.random.default_rng(0)
def fit(fn,p0,n=40):
    best=None
    for i in range(n):
        p=np.array(p0,dtype=float)*(10**rng.uniform(-2,2,len(p0)))
        try:
            r=least_squares(lambda p: fn(p)-J,p)
            rr=fn(r.x)-J
            m=np.mean(rr*rr)
            if best is None or m<best[0]: best=(m,np.mean(np.abs(rr/J)),r.x)
        except: pass
    return best
vars_={'Ci':Ci,'Co':Co,'J':J,'V':V}
# variant: (Ci-Co e^{+BV})/(1-e^{+BV})
cands={
 'frac_plus':lambda p: p[0]*V*(Ci-Co*np.exp(p[1]*V))/(1-np.exp(p[1]*V)),
 'frac_revCo':lambda p: p[0]*V*(Co-Ci*np.exp(-p[1]*V))/(1-np.exp(-p[1]*V)),
 'frac_revCo_plus':lambda p: p[0]*V*(Co-Ci*np.exp(p[1]*V))/(1-np.exp(p[1]*V)),
 'noV_plus':lambda p: p[0]*(Ci-Co*np.exp(p[1]*V))/(1-np.exp(p[1]*V)),
 'noV_rev':lambda p: p[0]*(Co-Ci*np.exp(-p[1]*V))/(1-np.exp(-p[1]*V)),
}
for k,f in cands.items():
    try:
        r=fit(f,[1e8,40])
        print(k,'rmse=%.2e rel=%.4f x=%s'%(r[0]**0.5,r[1],np.round(r[2],4)))
    except Exception as e: print(k,'ERR',str(e)[:40])
